// theme download. Unreachable is set only when the network attempt itself
// failed — never for an individual file's own error, which is not this
// project's fault to explain to the user.
type RemoteThemesFetchedMsg struct {
	Added       []string
	Unreachable bool
}

func fetchRemoteThemesCmd() tea.Cmd {
	return func() tea.Msg {
		existing, _ := theme.ListThemes()
		have := make(map[string]bool, len(existing))
		for _, name := range existing {
			have[name] = true
		}

		dir, err := theme.ThemeDir()
		if err != nil {
			return RemoteThemesFetchedMsg{Unreachable: true}
		}

		client := &http.Client{Timeout: remoteThemeFetchTimeout}
		var added []string
		for _, name := range knownRemoteThemes {
			if have[name] {
				continue
			}
			data, err := fetchRemoteTheme(client, name)
			if err != nil {
				if len(added) == 0 {
					// Nothing has succeeded yet, so this reads as "no
					// network" rather than "this one file is missing" — a
					// 404 on the project's own bundled theme would be a
					// repository mistake, not something worth retrying 11
					// more times for.
					return RemoteThemesFetchedMsg{Unreachable: true}
// forgeType and v name the tab and its words. The tab is titled after the
// platform the context targets, not after the section key: `forge:` is what the
// file says, and no user calls it that.
//
// contextName is the name of the context being edited; the config does not
// carry it, which is the same reason configPath is passed.
func sections(themes, views []string, configPath, contextName, forgeType string, v forge.Vocabulary, mcp MCPFacts) []section {
	return []section{
		{Title: "app", Fields: slices.Concat(
			group("Appearance", theme.IconDashboard,
				cycle("Theme", func(c *config.Config) *string { return &c.App.Theme }, themes,
					"Applied as you cycle it"),
				cycle("Default view", func(c *config.Config) *string { return &c.App.DefaultView }, views,
					"The view DevDesk opens on"),
				cycle("Gauge glyph", func(c *config.Config) *string { return &c.App.GaugeGlyph },
					config.GaugeGlyphs(), "block fills with a solid █, which some terminals draw double-width"),
				cycleWithDefault(motionLabel, func(c *config.Config) *string { return &c.App.Motion },
					config.Motions(), config.DefaultMotion,
					"static keeps a running row's dot steady — no blinking, no periodic redraw"),
				cycleWithDefault(whenUnfocusedLabel, func(c *config.Config) *string { return &c.App.WhenUnfocused },
					config.WhenUnfocusedModes(), config.DefaultWhenUnfocused,
					"pause suspends the animation and the periodic reads while the terminal has no focus"),
			),
			group("Paths", theme.IconDirectory,
				pathField("Workspaces dir", func(c *config.Config) *string { return &c.App.WorkspacesDir },
					"Root the workspaces view browses", filebrowser.PickDir),
}

// cycleField advances a closed-set field (Rule 132).
func (m Model) cycleField(step int) (tea.Model, tea.Cmd) {
	f := m.current()
	if f.Kind != kindCycle {
		return m, nil
	}
	f.Cycle(m.config, step)

	// The theme is the one setting whose effect is the screen itself, so it is
	// applied as it is cycled rather than on blur — otherwise the user is
	// choosing blind.
	if f.Label == themeLabel {
		return m, m.persist(saved{theme: true})
	}
	// The backend is confirmed on blur, so nothing is written here.
	if f.Label == secretBackendLabel {
		return m, nil
	}
	// The engine is settled on blur, same reasoning: cycling auto → docker →

